}","class":"https://www.commoncoreontologies.org/ont00000965","handle":"c360.semsource-696621.workspace.golang.struct.processor-url-source-config-go-Config"},{"name":"loadCommunities","kind":"function","path":"scripts/measure-communities/main.go","lines":[108,139],"body":"func loadCommunities(ctx context.Context, js jetstream.JetStream) (map[int][]community, error) {
	kv, err := js.KeyValue(ctx, "COMMUNITY_INDEX")
	if err != nil {
		return nil, fmt.Errorf("open COMMUNITY_INDEX (clustering may not have run yet): %w", err)
	}
	keys, err := kv.Keys(ctx)
	if err != nil {
		return nil, fmt.Errorf("list COMMUNITY_INDEX keys: %w", err)
	}

	byLevel := map[int][]community{}
	for _, k := range keys {
		if strings.HasPrefix(k, "entity.") {
			continue
		}
		e, err := kv.Get(ctx, k)
		if err != nil {
			continue
		}
		var c community
		if err := json.Unmarshal(e.Value(), &c); err != nil {
			continue
		}
		if len(c.Members) > 0 {
			byLevel[c.Level] = append(byLevel[c.Level], c)
		}
	}
	if len(byLevel) == 0 {
		return nil, fmt.Errorf("no communities with members found in COMMUNITY_INDEX (%d keys)", len(keys))
	}
	return byLevel, nil
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-696621.workspace.golang.function.scripts-measure-communities-main-go-loadCommunities"},{"name":"TestResolveMode","kind":"function","path":"source/fusion/lens/docs/docs_test.go","lines":[18,53],"body":"func TestResolveMode(t *testing.T) {
