	bucket, err := h.js.KeyValue(h.ctx, "GRAPH_INGEST_APPLIED_SEQ")
	if err != nil {
		return
	}
	entry, err := bucket.Get(h.ctx, h.ids["run"]+"/GRAPH")
	if err != nil || (len(entry.Value()) != 8 && len(entry.Value()) != 16) {
		return
	}
	stream, err := h.js.Stream(h.ctx, "GRAPH")
	if err != nil {
		return
	}
	info, err := stream.Info(h.ctx)
	if err != nil {
		return
	}
	var sequences []uint64
	for seq := info.State.FirstSeq; seq <= info.State.LastSeq; seq++ {
		msg, getErr := stream.GetMsg(h.ctx, seq)
		if getErr == nil && bytes.Contains(msg.Data, []byte(h.ids["run"])) {
			sequences = append(sequences, seq)
		}
	}
	var appliedGeneration, appliedSeq uint64
	if len(entry.Value()) == 16 {
		appliedGeneration = binary.BigEndian.Uint64(entry.Value()[:8])
		appliedSeq = binary.BigEndian.Uint64(entry.Value()[8:16])
	} else {
		appliedSeq = binary.BigEndian.Uint64(entry.Value())
	}
	raw, err := json.MarshalIndent(map[string]any{
		"guard_key":                      entry.Key(),
		"applied_generation":             appliedGeneration,
		"applied_sequence":               appliedSeq,
		"restarted_stream_last_sequence": info.State.LastSeq,
		"run_payload_sequences":          sequences,
	}, "", "  ")
	if err == nil {
		h.save("restart-guard.json", raw)
	}
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-696621.workspace.golang.method.test-setup03a-qualification_test-go-harness-captureRestartGuard"},{"name":"TestAbsentSet_ReappearedArtifactIsCleared","kind":"function","path":"processor/supersession/lifecycle_absent_test.go","lines":[167,197],"body":"func TestAbsentSet_ReappearedArtifactIsCleared(t *testing.T) {
