	fields := strings.Fields(info)
	var marker string
	for _, f := range fields {
		if strings.HasPrefix(f, "quickstart") {
			if marker != "" {
				return nil, fmt.Errorf("multiple quickstart markers in info string %q", info)
			}
			marker = f
		}
	}
	if marker == "" {
		return nil, nil
	}
	rest, ok := strings.CutPrefix(marker, "quickstart:")
	if !ok || rest == "" {
		return nil, fmt.Errorf("malformed quickstart marker %q (want quickstart:<track>[,<track>])", marker)
	}
	var tracks []string
	seen := map[string]bool{}
	for _, tr := range strings.Split(rest, ",") {
		if !quickstartTracks[tr] {
			return nil, fmt.Errorf("unknown track %q in marker %q (valid: single, multi)", tr, marker)
		}
		if seen[tr] {
			return nil, fmt.Errorf("duplicate track %q in marker %q", tr, marker)
		}
		seen[tr] = true
		tracks = append(tracks, tr)
	}
	return tracks, nil
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-696621.workspace.golang.function.test-e2e-quickstart_doc-go-parseMarker"},{"name":"staleness_lifecycle_integration_test.go","kind":"file","path":"internal/governance/staleness_lifecycle_integration_test.go","lines":[1,264],"class":"https://www.commoncoreontologies.org/ont00000798","handle":"c360.semsource-696621.workspace.golang.file.internal-governance-staleness_lifecycle_integration_test-go"},{"name":"assertStalenessRemovalAbsent","kind":"function","path":"internal/governance/staleness_lifecycle_integration_test.go","lines":[253,264],"body":"func assertStalenessRemovalAbsent(ctx context.Context, t *testing.T, client *natsclient.Client, ids ...string) {
