	dir := t.TempDir()
	content := "# Guide\n\n" + prose("intro", 4) +
		headedSection("Usage", "usage", 4) +
		headedSection("Limits", "limits", 4)
	writeMD(t, dir, "guide.md", content)

	h, store := docsHandler(t)
	cfg := sourceConfig{typ: "docs", path: dir}

	states, err := h.IngestEntityStates(context.Background(), cfg, testAuthority("acme"))
	if err != nil {
		t.Fatalf("IngestEntityStates() error: %v", err)
	}
	passages := passageStates(states)
	if len(passages) < 2 {
		t.Fatalf("passage state count: got %d, want at least 2; with one passage a whole-file blob is legitimate and this test proves nothing",
			len(passages))
	}

	// The passages tile the document: concatenating their bodies reproduces the
	// file byte for byte, so the split loses nothing.
	referenced := make(map[string]bool, len(passages))
	var joined strings.Builder
	for _, passage := range passages {
		referenced[tripleValue(t, passage, source.DocBodyKey)] = true
		joined.WriteString(passageBody(t, store, passage))
	}
	if joined.String() != content {
		t.Errorf("passage bodies concatenated to %d bytes, want the whole %d-byte document",
			joined.Len(), len(content))
	}

	// Nothing in the store is unreferenced: a parent blob would be a surplus key.
	keys := store.keys()
	if len(keys) != len(referenced) {
		t.Errorf("store holds %d blobs %v, want %d (one per distinct passage key; a surplus blob is a duplicated body)",
			len(keys), keys, len(referenced))
	}
	for _, key := range keys {
		if !referenced[key] {
			t.Errorf("store holds blob %q that no passage handle references; the parent must offload nothing", key)
		}
		blob, err := store.Get(context.Background(), key)
		if err != nil {
			t.Fatalf("store key %q reported by keys() but not gettable: %v", key, err)
		}
		if string(blob) == content {
			t.Errorf("store blob %q holds the entire %d-byte document; the text must reach the store only in passage-sized pieces",
				key, len(content))
		}
	}
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-696621.workspace.golang.function.handler-doc-handler_test-go-TestDocHandler_IngestEntityStates_DocumentTextStoredExactlyOnce"},{"name":"TestContentSeam_MatchesFileIngest","kind":"function","path":"handler/doc/content_seam_test.go","lines":[92,141],"body":"func TestContentSeam_MatchesFileIngest(t *testing.T) {
	system := entityid.SystemSlug(seamProject)

	for _, fx := range seamFixtures {
		t.Run(fx.name, func(t *testing.T) {
			dir := t.TempDir()
			writeDocAt(t, dir, fx.relPath, fx.content)

			h := seamHandler(t)
			fileStates, err := h.IngestEntityStates(context.Background(),
				sourceConfig{typ: "docs", path: dir}, testAuthority("acme"))
			if err != nil {
				t.Fatalf("IngestEntityStates() error: %v", err)
			}

			contentStates, err := h.IngestContentEntityStates(context.Background(),
				[]byte(fx.content), fx.relPath, system, testAuthority("acme"), time.Now().UTC())
			if err != nil {
				t.Fatalf("IngestContentEntityStates() error: %v", err)
			}

			if len(fileStates) == 0 {
				t.Fatalf("file ingest produced no states for %q", fx.relPath)
			}
			gotFile, gotContent := comparableStates(fileStates), comparableStates(contentStates)
			if len(gotFile) != len(gotContent) {
				t.Fatalf("state count: file ingest %d, content seam %d", len(gotFile), len(gotContent))
			}
			for i := range gotFile {
				if gotFile[i].id != gotContent[i].id {
					t.Errorf("state %d ID: file %q, content %q", i, gotFile[i].id, gotContent[i].id)
				}
				if gotFile[i].profile != gotContent[i].profile {
					t.Errorf("state %d indexing profile: file %q, content %q",
						i, gotFile[i].profile, gotContent[i].profile)
				}
				if len(gotFile[i].triples) != len(gotContent[i].triples) {
					t.Fatalf("state %d triple count: file %d, content %d",
						i, len(gotFile[i].triples), len(gotContent[i].triples))
				}
				for j := range gotFile[i].triples {
					if gotFile[i].triples[j] != gotContent[i].triples[j] {
						t.Errorf("state %d triple %d:\n  file:    %s\n  content: %s",
							i, j, gotFile[i].triples[j], gotContent[i].triples[j])
					}
				}
			}
		})
	}
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-696621.workspace.golang.function.handler-doc-content_seam_test-go-TestContentSeam_MatchesFileIngest"}],"truncated":true,"contract_version":"2"}

