	parts := strings.Split(name, ".")
	if len(parts) < 3 {
		return RoleMetadata
	}

	category := parts[len(parts)-2]
	switch category {
	case "relationship", "structure", "dependency":
		return RoleRelationship
	case "metric":
		return RoleMetric
	}

	// Check by second segment (domain.category.property pattern)
	if len(parts) >= 3 {
		switch parts[1] {
		case "relationship", "structure", "dependency":
			return RoleRelationship
		case "metric":
			return RoleMetric
		}
	}

	return RoleMetadata
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-696621.workspace.golang.function.processor-source-manifest-status-go-patternRole"},{"name":"ResolveMode","kind":"method","path":"source/fusion/lens/docs/docs.go","lines":[54,66],"body":"func (*Lens) ResolveMode(query string) fusion.ResolveMode {
