	if node.Type() != "relative_import" {
		return nodeText(node, content), 0
	}
	for i := 0; i < int(node.NamedChildCount()); i++ {
		child := node.NamedChild(i)
		switch child.Type() {
		case "import_prefix":
			level = strings.Count(nodeText(child, content), ".")
		case "dotted_name":
			module = nodeText(child, content)
		}
