	var out [][2]int
	start := blk[0]
	last := blk[0]
	for _, end := range sentenceEnds(content, blk) {
		if end-start > b.ceiling && last > start {
			out = append(out, [2]int{start, last})
			start = last
		}
		for end-start > b.hardMax {
			cut := runeBoundary(content, start+b.hardMax)
			out = append(out, [2]int{start, cut})
			start = cut
		}
		last = end
	}
	if blk[1] > start {
		for blk[1]-start > b.hardMax {
			cut := runeBoundary(content, start+b.hardMax)
			out = append(out, [2]int{start, cut})
			start = cut
		}
		out = append(out, [2]int{start, blk[1]})
	}
	return out
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-696621.workspace.golang.function.handler-doc-splitter-go-cutOnSentences"},{"name":"TestHarnessFailsFastAfterApplicationExit","kind":"function","path":"test/setup03a/lifecycle_test.go","lines":[14,40],"body":"func TestHarnessFailsFastAfterApplicationExit(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	out := t.TempDir()
	binary := filepath.Join(out, "failed-start")
	if err := os.WriteFile(binary, []byte("#!/bin/sh\nexit 23\n"), 0700); err != nil {
		t.Fatal(err)
	}
	h := &harness{t: t, ctx: ctx, out: out, binary: binary}
	h.start()
	defer h.stop(false)
	select {
	case <-h.exited:
	case <-ctx.Done():
		t.Fatal("failed-start subprocess did not exit")
	}
	queried := false
	if h.poll(time.Minute, func() bool { queried = true; return false }) {
		t.Fatal("exited application reported ready")
	}
	if queried {
		t.Fatal("readiness continued polling after the application exited")
	}
	if err := h.applicationExit(); err == nil || !strings.Contains(err.Error(), "exit status 23") {
		t.Fatalf("lost concrete application exit: %v", err)
	}
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-696621.workspace.golang.function.test-setup03a-lifecycle_test-go-TestHarnessFailsFastAfterApplicationExit"},{"name":"visit","kind":"method","path":"source/ast/cpp/parser.go","lines":[125,204],"body":"func (p *Parser) visit(node *sitter.Node, content []byte, relPath string, scope []string, out emit) {
	topLevel := len(scope) == 0

	switch node.Type() {
	case "namespace_definition":
		// A namespace is recorded as a type rather than a package: the package
		// entity type deliberately drops the name from its instance ID, so two
		// namespaces in one file would collide on a single identity.
		name := nodeText(node.ChildByFieldName("name"), content)
		if name != "" {
			entity := p.newEntity(ast.TypeType, name, relPath, scope, node)
			entity.DocComment = docComment(node, content)
			out(entity, topLevel)
		}
		if body := node.ChildByFieldName("body"); body != nil {
			p.walk(body, content, relPath, append(scope, name), out)
		}

	case "template_declaration":
		// The templated class or function is an unnamed child alongside the
		// parameter list. Instantiations are not visible without a compiler, so
		// the declaration is what gets indexed.
		for i := 0; i < int(node.NamedChildCount()); i++ {
			child := node.NamedChild(i)
			if child.Type() != "template_parameter_list" {
				p.visit(child, content, relPath, scope, out)
			}
		}

	case "class_specifier", "struct_specifier", "union_specifier":
		p.classEntity(node, content, relPath, scope, out)

	case "enum_specifier":
		if name := nodeText(node.ChildByFieldName("name"), content); name != "" {
			entity := p.newEntity(ast.TypeEnum, name, relPath, scope, node)
			entity.DocComment = docComment(node, content)
			out(entity, topLevel)
		}

	case "alias_declaration":
		if name := nodeText(node.ChildByFieldName("name"), content); name != "" {
			entity := p.newEntity(ast.TypeType, name, relPath, scope, node)
			entity.DocComment = docComment(node, content)
			out(entity, topLevel)
		}

	case "type_definition":
		if name := declaratorName(node.ChildByFieldName("declarator"), content); name != "" {
			entity := p.newEntity(ast.TypeType, name, relPath, scope, node)
			entity.DocComment = docComment(node, content)
			out(entity, topLevel)
		}

	case "function_definition", "declaration", "field_declaration":
		p.callableOrField(node, content, relPath, scope, out)

	case "preproc_def", "preproc_function_def":
		if name := nodeText(node.ChildByFieldName("name"), content); name != "" {
			entity := p.newEntity(ast.TypeConst, name, relPath, scope, node)
			if params := node.ChildByFieldName("parameters"); params != nil {
				entity.Signature = name + params.Content(content)
			}
			entity.DocComment = docComment(node, content)
			out(entity, topLevel)
		}

	case "preproc_ifdef", "preproc_if", "preproc_else", "preproc_elif",
		"preproc_ifdef_in_field_declaration_list", "preproc_if_in_field_declaration_list":
		// Both branches are read — see the C parser for why. A symbol appearing
