{"provenance":"lexical","nodes":[{"name":"callTargetID","kind":"method","path":"source/ast/python/calls.go","lines":[292,329],"body":"func (p *Parser) callTargetID(fn *sitter.Node, content []byte, filePath string, scope []string, classMethods, locals map[string]bool) string {
	if fn == nil {
		return ""
	}
	switch fn.Type() {
	case "identifier":
		name := nodeText(fn, content)
		if locals[name] {
			return "" // shadowed by a parameter/local — a call through that VALUE, not a definition reference
		}
		return p.callNameToEntityID(name, filePath)
	case "attribute":
		obj := fn.ChildByFieldName("object")
		attr := fn.ChildByFieldName("attribute")
		if obj == nil || attr == nil {
			return ""
		}
		objText := nodeText(obj, content)
		method := nodeText(attr, content)
		// self.method() / cls.method() — resolve only to a method of THIS class;
		// inherited/mixin methods (defined in another file) stay inert. self/cls
		// are fixed receiver names, not subject to the locals shadow check: a
		// parameter literally named "self" other than the true self parameter
		// would BE the self parameter, so there is no separate shadow to guard.
		if objText == "self" || objText == "cls" {
			if len(scope) > 0 && classMethods[method] {
				return ast.NewScopedCodeEntity(p.authority, "python", p.project, ast.TypeMethod, scope, method, filePath).ID
			}
			return ""
		}
		if locals[objText] {
			return "" // objText is a local value, not an imported module/alias
		}
		// module.func() where the receiver head is an imported module/alias.
		return p.resolveImportedCallee(objText+"."+method, filePath)
	}
	return ""
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-696621.workspace.golang.method.source-ast-python-calls-go-Parser-callTargetID"},{"name":"TestPlainTextStillProducesAnonymousPassages","kind":"function","path":"handler/doc/asciidoc_test.go","lines":[135,146],"body":"func TestPlainTextStillProducesAnonymousPassages(t *testing.T) {
