	dir := t.TempDir()
	body := "# Guide\n\n" + prose("intro", 4) +
		headedSection("Usage", "usage", 4) +
		headedSection("Limits", "limits", 4)
	path := writeMD(t, dir, "guide.md", body)

	h, _ := docsHandler(t)
	before := passageStates(ingestDocs(t, h, dir))
	if len(before) < 2 {
		t.Fatalf("passage state count before the rename: got %d, want at least 2", len(before))
	}

	renamed := strings.Replace(body, "## Usage\n", "## Getting Started\n", 1)
	if renamed == body {
		t.Fatal("fixture error: the heading rename did not change the document")
	}
	if err := os.WriteFile(path, []byte(renamed), 0644); err != nil {
		t.Fatalf("WriteFile: %v", err)
	}

	after := passageStates(ingestDocs(t, h, dir))
	if len(before) != len(after) {
		t.Fatalf("passage count changed on a heading rename: %d then %d (renaming a heading must not restructure the document)",
			len(before), len(after))
	}
	for i := range before {
		if before[i].ID != after[i].ID {
			t.Errorf("passage %d ID changed when only a heading's text changed: %q then %q; identity is (path, ordinal), not the heading slug",
				i, before[i].ID, after[i].ID)
		}
	}

	// Guard against a vacuous pass: the rename must actually have reached the
	// passage's facts, otherwise the IDs above are stable for the wrong reason.
	if got := tripleValue(t, before[1], source.DocSection); got != "Usage" {
		t.Fatalf("%s on passage 1 before the rename = %q, want %q", source.DocSection, got, "Usage")
	}
	if got := tripleValue(t, after[1], source.DocSection); got != "Getting Started" {
		t.Errorf("%s on passage 1 after the rename = %q, want %q (the new heading text must land on the same entity)",
			source.DocSection, got, "Getting Started")
	}
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-696621.workspace.golang.function.handler-doc-passage_test-go-TestDocHandler_Passages_HeadingRenameKeepsIDs"},{"name":"Resolve","kind":"method","path":"processor/code-context/exact_seed.go","lines":[34,67],"body":"func (c exactSeedClient) Resolve(ctx context.Context, q fusion.ResolveQuery) (fusion.Resolution, error) {
	res, err := c.RetrievalClient.Resolve(ctx, q)
	if err != nil || q.Mode != fusion.ResolveModeSymbol || len(res.Seeds) == 0 {
		return res, err
	}
	hydration, err := c.RetrievalClient.Entities(ctx, fusion.SeedIDs(res.Seeds))
	if err != nil {
		// A backend failure must stay a failure (ready ≠ not-found): silently
		// returning the unfiltered seeds would defeat the filter exactly when
		// the graph is degraded.
		return fusion.Resolution{}, err
	}
	want := strings.TrimSpace(q.Query)
	keep := make(map[string]bool, len(hydration.Entities))
	for _, e := range hydration.Entities {
		if e.First(ast.DcTitle) == want {
			keep[e.ID] = true
		}
	}
	// A seed that did not hydrate is dropped, because its display name could not
	// be read and this filter's entire claim is byte-exactness — asserting it for
	// an entity we never saw would admit exactly the lookalike this exists to
	// prevent. Since beta.157 that drop is at least KNOWABLE: hydration.Unhydrated
	// names every such ID with a reason (gh#597), where before it was
	// indistinguishable from a shorter slice.
	exact := make([]fusion.Seed, 0, len(res.Seeds))
	for _, s := range res.Seeds {
		if keep[s.ID] {
			exact = append(exact, s)
		}
	}
	res.Seeds = exact
	return res, nil
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-696621.workspace.golang.method.processor-code-context-exact_seed-go-exactSeedClient-Resolve"},{"name":"sectionsOf","kind":"function","path":"handler/doc/splitter.go","lines":[177,225],"body":"func sectionsOf(lines []line, total int, f docFormat) []section {
