	names := make(map[string]bool)
	body := classNode.ChildByFieldName("body")
	if body == nil {
		return names
	}
	for i := 0; i < int(body.NamedChildCount()); i++ {
		child := body.NamedChild(i)
		var def *sitter.Node
		switch child.Type() {
		case "function_definition":
			def = child
		case "decorated_definition":
			def = findFunctionInDecorated(child)
		}
		if def != nil {
			if nameNode := def.ChildByFieldName("name"); nameNode != nil {
				names[nodeText(nameNode, content)] = true
			}
		}
	}
	return names
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-696621.workspace.golang.function.source-ast-python-calls-go-classMethodNames"},{"name":"TestMemberCallOnNonNamespaceIdentifierStaysInert","kind":"function","path":"source/ast/ts/calls_test.go","lines":[171,176],"body":"func TestMemberCallOnNonNamespaceIdentifierStaysInert(t *testing.T) {
