{"provenance":"lexical","nodes":[{"name":"minifiedFileResult","kind":"method","path":"processor/ast-source/assetguard.go","lines":[96,153],"body":"func (c *Component) minifiedFileResult(pw *pathWatcher, filePath, routeLang string) *semsourceast.ParseResult {
	base := filepath.Base(filePath)
	byName := isMinifiedName(base)

	if !byName {
		info, err := os.Stat(filePath)
		if err != nil || info.Size() < minifiedProbeMinSize {
			return nil
		}
		f, err := os.Open(filePath)
		if err != nil {
			return nil
		}
		sample := make([]byte, minifiedProbeLimit)
		n, _ := io.ReadFull(f, sample)
		_ = f.Close()
		if !isMinifiedContent(sample[:n], info.Size()) {
			return nil
		}
	}

	content, err := os.ReadFile(filePath)
	if err != nil {
		return nil
	}
	relPath, err := filepath.Rel(pw.root, filePath)
	if err != nil {
		return nil
	}

	how := "shape"
	if byName {
		how = "name"
	}
	c.logger.Debug("minified asset — indexing file entity only, skipping symbol extraction",
		"path", relPath, "detected_by", how)

	hash := semsourceast.ComputeHash(content)
	ext := strings.ToLower(filepath.Ext(filePath))
	fileEntity := semsourceast.NewCodeEntity(
		c.authority,
		entityDomainForRoute(routeLang, ext),
		pw.scopedSystem,
		semsourceast.TypeFile,
		base,
		relPath,
	)
	fileEntity.Hash = hash
	fileEntity.StartLine = 1
	fileEntity.EndLine = bytes.Count(content, []byte("\n")) + 1

	return &semsourceast.ParseResult{
		FileEntity: fileEntity,
		Entities:   []*semsourceast.CodeEntity{fileEntity},
		Path:       relPath,
		Hash:       hash,
	}
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-696621.workspace.golang.method.processor-ast-source-assetguard-go-Component-minifiedFileResult"},{"name":"prefixQuerier","kind":"struct","path":"processor/supersession/prefixquery.go","lines":[31,35],"body":"type prefixQuerier struct {
