	t.Helper()
	deadline := time.Now().Add(retryFor)
	for {
		cmd := exec.Command("bash", "-c", e.wrapScript(script, true))
		cmd.Env = e.env
		var out bytes.Buffer
		cmd.Stdout = &out
		cmd.Stderr = &out
