	c.mu.Lock()
	if c.running {
		c.mu.Unlock()
		return fmt.Errorf("component already running")
	}
	c.mu.Unlock()

	runCtx := context.WithoutCancel(ctx)
	c.publisher.Start(runCtx)
	c.initBodyStore(ctx)

	c.seedLoss.Begin(c.publisher.Lost())
	c.publishStatusReport(ctx, "ingesting")

	c.startProgressReporting(runCtx)

	// Everything from here is unbounded — the path retry alone is ~30 attempts —
	// so it runs in a supervised goroutine and Start returns. Holding the
	// lifecycle hook across it blocks the framework's component-start barrier,
	// which in turn prevents the HTTP status and metrics listeners from binding
	// at all (semstreams#867): the surfaces stay dark for the whole seed, which
	// is exactly when an operator needs them.
	c.markRunning()
	c.seed.Start(runCtx, c.logger, c.runSeed)
	return nil
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-696621.workspace.golang.method.processor-ast-source-component-go-Component-Start"},{"name":"onRetry","kind":"var","path":"ui/src/lib/components/WorkbenchShell.svelte","lines":[21,21],"body":"    error,","class":"https://www.commoncoreontologies.org/ont00000965","handle":"c360.semsource-696621.workspace.svelte.var.ui-src-lib-components-WorkbenchShell-svelte-onRetry"},{"name":"LossyPublisher","kind":"function","path":"internal/statustest/publisher.go","lines":[47,93],"body":"func LossyPublisher(t *testing.T, n int) (*entitypub.Publisher, int64) {
	t.Helper()
	pub, err := entitypub.New(refusing{}, discardLogger(),
		entitypub.WithCapacity(max(n, 1)*2),
		entitypub.WithSendTimeout(time.Second),
		// Microsecond backoffs so the terminal-failure sequence completes in
		// milliseconds instead of running out the delivery budget.
		entitypub.WithRetryBackoff(time.Microsecond, 10*time.Microsecond))
	if err != nil {
		t.Fatalf("statustest: new publisher: %v", err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	pub.Start(ctx)
	t.Cleanup(func() {
		cancel()
		_ = pub.Stop(context.Background())
	})

	var accepted int64
	for i := 0; i < n; i++ {
		if pub.Send(&graph.EntityPayload{
			ID:                  "org.semsource.golang.sys.function.statustest",
			UpdatedAt:           time.Now(),
			IndexingProfileHint: graph.IndexingProfileContent,
		}) == nil {
			accepted++
		}
	}

	deadline := time.Now().Add(20 * time.Second)
	for time.Now().Before(deadline) {
		if pub.Pending() == 0 && pub.Published()+pub.Lost() >= accepted+pub.Dropped() {
			break
		}
		time.Sleep(time.Millisecond)
	}
	if pub.Pending() != 0 {
		t.Fatalf("statustest: publisher never settled: pending=%d", pub.Pending())
	}
	if pub.Lost() == 0 {
		t.Fatal("statustest: no loss produced; a delivery assertion would prove nothing")
	}
	if got := pub.Published(); got != 0 {
		t.Fatalf("statustest: Published() = %d, want 0", got)
